<script setup>
import { computed, ref, watch, nextTick, onBeforeUnmount } from 'vue';
import axios from 'axios';
import Swal from '../services/localizedSwal.js';
import { formatMoney, formatDate } from '../languageConfig.js';
const emit=defineEmits(['navigate', 'signed-out', 'toggle-dark-mode', 'catalog-updated']);
const client=axios.create({baseURL:(import.meta.env.VITE_API_URL || 'http://localhost:5000/api')+'/admin',timeout:20000});
const token=ref(sessionStorage.getItem('safeher-admin-token')||'');
const email=ref(''),password=ref(''),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('dashboard'),rows=ref([]),counts=ref({}),categories=ref([]),editor=ref(null),detail=ref(null);
const metricInfo={users:{icon:'bi-people',note:'Registered accounts'},orders:{icon:'bi-bag-check',note:'All customer orders'},revenue:{icon:'bi-wallet2',note:'Paid orders, excluding card demos'},pending_orders:{icon:'bi-hourglass-split',note:'Awaiting payment confirmation'},low_stock:{icon:'bi-box-seam',note:'Active products with 5 or fewer left'},active_subscriptions:{icon:'bi-gem',note:'Current premium memberships'}};
const search=ref('');
const columnsByTab={dashboard:['order_number','total','status','payment_status','created_at'],orders:['order_number','customer_name','total','status','payment_status','delivery_method'],products:['name','price','stock','is_active'],reviews:['name','type','stars','content','is_approved'],users:['name','email','phone','is_admin'],premium:['customer','plan','amount','expires_at','active'],lessons:['title','duration','order_number','is_premium'],safety:['metric','count']};
const columns=computed(()=>columnsByTab[tab.value]||[]);
const descriptions={dashboard:'Your store and community at a glance.',orders:'Follow each order from checkout to delivery.',products:'Curate the essentials your customers rely on.',reviews:'Give customer feedback a thoughtful review.',users:'Your growing SafeHer community.',premium:'Memberships and access, in one place.',lessons:'Keep your safety library useful and up to date.',safety:'A private, aggregate view of safety activity.'};
async function toggleProduct(row){
 const next=!row.is_active;
 const result=await Swal.fire({title:next?'Restore this product?':'Remove this product from the store?',text:next?'Customers will be able to browse this product again.':'This hides the product from customers and preserves existing orders. You can restore it later.',showCancelButton:true,confirmButtonText:next?'Restore':'Remove from store',confirmButtonColor:'#713650'});
 if(!result.isConfirmed)return;
 busy.value=true;error.value='';try{await request('patch','/products/'+row.id+'/visibility',{is_active:next});notice.value=next?'Product restored.':'Product removed from the store.';emit('catalog-updated');await load();}catch(e){error.value=e.response?.data?.error||'Unable to update product.';}finally{busy.value=false;}
}

const filteredRows=computed(()=>rows.value.filter(row=>Object.values(row).some(value=>String(value??'').toLowerCase().includes(search.value.toLowerCase()))));
const icons={dashboard:'bi-grid',orders:'bi-bag',products:'bi-box-seam',reviews:'bi-chat-square-text',users:'bi-people',premium:'bi-gem',lessons:'bi-play-circle',safety:'bi-shield-check'};
const tabs=['dashboard','orders','products','reviews','users','premium','lessons','safety'];
const labels={dashboard:'Dashboard',orders:'Orders',products:'Products',reviews:'Reviews',users:'Users',premium:'Premium',lessons:'Lessons',safety:'Safety overview',users_count:'Users',pending_orders:'Pending orders',low_stock:'Low stock',active_subscriptions:'Active subscriptions',revenue:'Revenue'};
const fields={products:['name','slug','description','detail','price','image_url','category_id','stock','is_featured','is_active'],lessons:['title','slug','description','detail','duration','youtube_id','order_number','is_premium']};
function logout(){token.value='';sessionStorage.removeItem('safeher-admin-token');rows.value=[];counts.value={};editor.value=null;detail.value=null;}
async function request(method,path,data){try{return (await client.request({method,url:path,data,headers:{Authorization:`Bearer ${token.value}`}})).data;}catch(e){if([401,403].includes(e.response?.status))logout();throw e;}}
async function login(){if(busy.value)return;busy.value=true;error.value='';try{const {data}=await client.post('/login',{email:email.value,password:password.value});token.value=data.token;sessionStorage.setItem('safeher-admin-token',data.token);password.value='';await load();}catch(e){error.value=e.response?.data?.error||'Unable to sign in. Check your credentials and connection.';}finally{busy.value=false;}}
async function load(){error.value='';busy.value=true;try{const data=await request('get','/'+tab.value);rows.value=data.rows||data.recent||[];counts.value=data.counts||{};if(tab.value==='products')categories.value=(await request('get','/categories')).rows;}catch(e){error.value=e.response?.data?.error||'Unable to load admin data.';}finally{busy.value=false;}}
function select(next){if(busy.value)return;tab.value=next;search.value='';editor.value=null;detail.value=null;notice.value='';rows.value=[];load();}
function edit(row={}){error.value='';editor.value=Object.fromEntries(fields[tab.value].map(k=>[k,k.startsWith('is_')?Boolean(row[k]??(k==='is_active')):row[k]??(['stock','order_number','price'].includes(k)?0:k==='category_id'?categories.value[0]?.id:'')]));if(row.id)editor.value.id=row.id;notice.value='';}
async function uploadImage(event){
 const file=event.target.files?.[0];
 if(!file || busy.value)return;
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value='Choose a PNG, JPEG or WebP image up to 5 MB.';return;}
 busy.value=true;error.value='';notice.value='Uploading image...';
 try{const {data}=await client.post('/images',file,{timeout:40000,headers:{Authorization:`Bearer ${token.value}`,'Content-Type':file.type}});if(editor.value)editor.value.image_url=data.image_url;notice.value='Image uploaded. Save changes to update the product.';}
 catch(e){error.value=e.response?.data?.error||'Image upload failed. Please try again.';notice.value='';}
 finally{busy.value=false;event.target.value='';}
}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const data={...editor.value};await request(data.id?'put':'post','/'+tab.value+(data.id?'/'+data.id:''),data);editor.value=null;notice.value='Changes saved to the database.';if(tab.value==='products')emit('catalog-updated');await load();}catch(e){error.value=e.response?.data?.error||'Unable to save changes.';}finally{busy.value=false;}}
async function moderate(row){busy.value=true;try{await request('patch',`/reviews/${row.type}/${row.id}`,{is_approved:!row.is_approved});await load();}catch(e){error.value=e.response?.data?.error||'Unable to update review.';}finally{busy.value=false;}}
async function openOrder(row){
 if(busy.value)return;
 error.value='';detail.value=null;detailLoading.value=true;busy.value=true;
 try{detail.value=await request('get','/orders/'+row.id);}catch{error.value='Unable to load order. Close this panel and try again.';}
 finally{busy.value=false;detailLoading.value=false;}
}

const steps=['Confirmed','Packed','Out for delivery','Delivered'];
async function advance(row){busy.value=true;try{await request('patch','/orders/'+row.id,{status:steps[steps.indexOf(row.status)+1]});detail.value=null;await load();}catch(e){error.value=e.response?.data?.error||'Unable to update order.';}finally{busy.value=false;}}
const label=k=>labels[k]||k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const badgeTone=(key,value)=>['paid','Delivered',true,1].includes(value)?'status-positive':['pending','Packed','Out for delivery'].includes(value)?'status-pending':['failed',false,0].includes(value)?'status-muted':'';
const display=(key,value)=>value==null?'Not provided':key.includes('_at')?formatDate(value):key.startsWith('is_')||key==='active'?(value?'Yes':'No'):['price','total','amount','revenue'].includes(key)?formatMoney(value):String(value);
const panel = ref(null), detailLoading = ref(false), panelOpen = ref(false);
let previousOverflow = '', returnFocus;
watch(() => Boolean(editor.value || detail.value || detailLoading.value), async open => {
 if(open && !panelOpen.value){
   returnFocus=document.activeElement;previousOverflow=document.body.style.overflow;
   panelOpen.value=true;await nextTick();panel.value?.showModal();document.body.style.overflow='hidden';
 } else if(!open && panelOpen.value && !error.value){closePanel(true);}
}, {flush:'post'});
function closePanel(force=false){
 if(busy.value && !force)return;
 editor.value=null;detail.value=null;detailLoading.value=false;panelOpen.value=false;
 panel.value?.close();document.body.style.overflow=previousOverflow;
 if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});
}
onBeforeUnmount(()=>{if(panelOpen.value)document.body.style.overflow=previousOverflow;});
if(token.value)load();
</script>
<template>
<main class="admin-shell">
<header><button class="admin-brand" @click="emit('navigate','index')">SafeHer <span>Administration</span></button><button class="btn btn-outline-plum" aria-label="Toggle colour theme" @click="emit('toggle-dark-mode')"><i class="bi bi-circle-half" aria-hidden="true" /></button><button v-if="token" class="btn btn-outline-plum" @click="logout(); emit('signed-out')">Sign out</button></header>
<p v-if="error" role="alert" class="admin-error">{{ error }}</p><p v-if="notice" class="admin-notice" role="status">{{ notice }}</p>
<section v-if="!token" class="admin-login"><p class="eyebrow">AUTHORISED STAFF</p><h1>Admin sign in.</h1><p>Use your admin account email and password.</p><form @submit.prevent="login"><label>Email<input v-model="email" type="email" required autocomplete="username" /></label><label>Password<input v-model="password" type="password" required autocomplete="current-password" /></label><button class="btn btn-dark-plum" :disabled="busy">{{ busy?'Signing in...':'Sign in' }}</button></form><button class="btn btn-outline-plum" @click="emit('navigate','login')">Reset password through customer sign-in</button></section>
<template v-else>
<nav aria-label="Admin sections"><button v-for="item in tabs" :key="item" :class="{selected:tab===item}" :aria-current="tab===item?'page':undefined" :disabled="busy" @click="select(item)"><i :class="`bi ${icons[item]}`" aria-hidden="true" />{{ label(item) }}</button></nav>
<div class="admin-heading"><div class="admin-title"><p class="eyebrow">SAFEHER / {{ label(tab).toUpperCase() }}</p><h1>{{ label(tab) }}.</h1><p>{{ descriptions[tab] }}</p></div><button class="btn btn-outline-plum" :disabled="busy" @click="load">Refresh</button><button v-if="fields[tab]" class="btn btn-dark-plum" :disabled="busy" @click="edit()">Add {{ tab==='products'?'product':'lesson' }}</button></div>
<p v-if="busy" class="request-status" role="status">Loading or saving admin data...</p>
<section v-if="tab==='dashboard'" class="admin-welcome"><p>YOUR SAFEHER WORKSPACE</p><h2>A clearer view of your community.</h2><span>Manage the store, support customers and keep your content up to date.</span></section><section v-if="tab==='dashboard'" class="dashboard-summary" aria-label="Dashboard totals"><div class="summary-heading"><h2>At a glance.</h2><span>Current database totals</span></div><div class="admin-metrics"><article v-for="(value,key) in counts" :key="key" :class="{'metric-revenue':key==='revenue'}"><div class="metric-top"><span class="metric-label">{{ label(key) }}</span><span class="metric-icon"><i :class="`bi ${metricInfo[key]?.icon || 'bi-bar-chart'}`" aria-hidden="true" /></span></div><strong>{{ key==='revenue'?formatMoney(value):value }}</strong><p>{{ metricInfo[key]?.note }}</p></article></div></section>
<p v-if="tab==='safety'">Aggregate counts only. Personal locations, messages and contact details are not shown.</p>
<dialog ref="panel" class="admin-side-panel" aria-labelledby="admin-panel-title" @cancel.prevent="closePanel()">
  <header class="admin-panel-heading"><div><p class="eyebrow">SAFEHER ADMIN</p><h2 id="admin-panel-title">{{ editor ? (editor.id ? 'Edit record.' : 'New record.') : 'Order details.' }}</h2></div><button type="button" class="btn btn-outline-plum" aria-label="Close panel" :disabled="busy" @click="closePanel()"><i class="bi bi-x-lg" aria-hidden="true" /></button></header>
  <p v-if="error" role="alert" class="admin-error">{{ error }}</p>
  <p v-if="detailLoading" class="request-status" role="status"><span class="request-spinner" aria-hidden="true" />Loading order details...</p>
<form v-if="editor" class="admin-editor" @submit.prevent="save"><h2>{{ editor.id?'Edit':'Add' }} {{ tab==='products'?'product':'lesson' }}.</h2><fieldset :disabled="busy"><label v-for="key in fields[tab]" :key="key">{{ label(key) }}<input v-if="key.startsWith('is_')" v-model="editor[key]" type="checkbox" /><select v-else-if="key==='category_id'" v-model.number="editor[key]" required><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select><textarea v-else-if="['description','detail'].includes(key)" v-model="editor[key]" rows="3" /><input v-else-if="['price','stock','order_number'].includes(key)" v-model.number="editor[key]" type="number" min="0" :step="key==='price'?'0.01':'1'" required /><input v-else v-model="editor[key]" :required="['name','title','slug'].includes(key)" /></label></fieldset><div v-if="tab==='products'"><label>Upload product image to ImgBB<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="uploadImage" /></label><p>PNG, JPEG or WebP, up to 5 MB. Paste a direct https://i.ibb.co image URL or upload a file.</p><img v-if="editor.image_url" :src="editor.image_url" alt="Product image preview" style="max-width:100%;height:160px;object-fit:contain" /></div><button class="btn btn-dark-plum" :disabled="busy">{{ busy ? 'Saving...' : 'Save changes' }}</button> <button type="button" class="btn btn-outline-plum" :disabled="busy" @click="closePanel()">Cancel</button></form>
<section v-if="detail" class="admin-editor"><h2>Order details.</h2><dl><template v-for="(value,key) in detail.order" :key="key"><dt>{{ label(key) }}</dt><dd>{{ display(key,value) }}</dd></template></dl><p v-for="(item,index) in detail.items" :key="index">{{ item.product_name }} &times; {{ item.quantity }} &mdash; {{ formatMoney(item.price_at_purchase) }}</p><button class="btn btn-outline-plum" @click="closePanel()">Close details</button></section>
</dialog>
<div class="admin-search"><label>Search this section<input v-model="search" type="search" placeholder="Search records..." /></label><span>{{ filteredRows.length }} records</span></div><div v-if="filteredRows.length && tab!=='products'" class="admin-table" tabindex="0" aria-label="Admin data"><table><caption class="visually-hidden">{{ label(tab) }} records</caption><thead><tr><th v-for="key in columns" :key="key" scope="col" :class="{'numeric-cell':['total','amount','count','stars','order_number'].includes(key) && key!=='order_number'}">{{ label(key) }}</th><th v-if="['orders','products','reviews','lessons'].includes(tab)">Actions</th></tr></thead><tbody><tr v-for="(row,index) in filteredRows" :key="`${row.type||tab}-${row.id||index}`"><td v-for="key in columns" :key="key" :class="{'numeric-cell':['total','amount','count','stars'].includes(key),'primary-cell':key===columns[0],'review-content-cell':key==='content'}"><span v-if="['status','payment_status','active','is_approved','is_admin','is_premium'].includes(key)" class="admin-status" :class="badgeTone(key,row[key])"><span class="status-dot" aria-hidden="true" />{{ display(key,row[key]) }}</span><span v-else-if="key==='stars'" class="table-rating"><i class="bi bi-star-fill" aria-hidden="true" /> {{ row[key] }}<small> / 5</small></span><span v-else>{{ display(key,row[key]) }}</span></td><td class="table-actions" v-if="['orders','products','reviews','lessons'].includes(tab)"><button v-if="fields[tab]" :disabled="busy" @click="edit(row)"><i class="bi bi-pencil" aria-hidden="true" /> Edit</button><template v-if="tab==='orders'"><button :disabled="busy" @click="openOrder(row)"><i class="bi bi-eye" aria-hidden="true" /> Details</button><button v-if="row.status!=='Delivered'&&row.payment_status==='paid'" :disabled="busy" @click="advance(row)">Move to {{ steps[steps.indexOf(row.status)+1] }}</button></template><button v-if="tab==='reviews'" :disabled="busy" @click="moderate(row)">{{ row.is_approved?'Hide':'Approve' }}</button></td></tr></tbody></table></div><section v-if="tab==='products' && filteredRows.length" class="admin-product-grid"><article v-for="product in filteredRows" :key="product.id" class="admin-product-card"><div class="admin-product-art"><img v-if="product.image_url" :src="product.image_url" :alt="product.name" loading="lazy" /><i v-else class="bi bi-box-seam" aria-hidden="true" /><span class="admin-status">{{ product.is_active?'Visible in store':'Hidden from store' }}</span></div><div class="admin-product-copy"><p>{{ categories.find(c=>c.id===product.category_id)?.name || 'Uncategorised' }}</p><h2>{{ product.name }}.</h2><div class="admin-product-facts"><strong>{{ formatMoney(product.price) }}</strong><span :class="{'low-stock':product.stock<=5}">{{ product.stock }} in stock</span></div><div class="admin-product-actions"><button class="btn btn-dark-plum" :disabled="busy" @click="edit(product)">Edit product</button><button class="btn btn-outline-plum" :disabled="busy" @click="toggleProduct(product)">{{ product.is_active?'Remove from store':'Restore' }}</button></div></div></article></section><p v-if="!busy && !filteredRows.length" class="admin-empty">{{ search?'No records match your search.':'No records to display yet.' }}</p>
</template>
</main>
</template>
<style scoped>
.admin-shell { padding:24px; max-width:1500px; margin:auto; color:var(--ink); min-height:100vh; }.admin-shell header,.admin-heading { display:flex; align-items:center; gap:18px; justify-content:space-between; flex-wrap:wrap; margin-bottom:24px; }.admin-brand { border:0; background:none; color:var(--ink); font-size:26px; font-weight:800; }.admin-brand span { font-size:13px; font-weight:400; }.admin-shell nav { display:flex; flex-wrap:wrap; gap:8px; margin:24px 0; }.admin-shell nav button,.admin-table button { padding:10px 14px; border:1px solid var(--control-border); background:var(--control-bg); color:var(--control-text); border-radius:8px; }.admin-shell nav .selected { background:var(--control-active); color:var(--control-active-text); }.admin-login { max-width:460px; margin:50px auto; }.admin-login form,.admin-editor fieldset { display:grid; gap:16px; margin:24px 0; }.admin-shell label { display:grid; gap:8px; }.admin-shell input,.admin-shell textarea,.admin-shell select { padding:12px; border:1px solid var(--control-border); border-radius:8px; background:var(--control-bg); color:var(--control-text); width:100%; }.admin-shell input[type=checkbox] { width:22px; height:22px; }.admin-error { border:1px solid #b94060; padding:16px; }.admin-metrics { display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:16px; }.admin-metrics article,.admin-editor { background:var(--surface); padding:24px; border:1px solid var(--line); border-radius:12px; }.admin-metrics strong { display:block; font-size:28px; margin-top:12px; }.admin-table { overflow:auto; margin-top:24px; }.admin-table table { border-collapse:collapse; width:100%; font-size:13px; }.admin-table th,.admin-table td { padding:12px; border-bottom:1px solid var(--line); text-align:left; min-width:100px; max-width:300px; overflow-wrap:anywhere; }.admin-table button { margin:3px; white-space:nowrap; }.admin-editor { margin:20px 0; }.admin-editor fieldset { grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); }.admin-shell button:focus-visible { outline:3px solid var(--control-active); outline-offset:3px; }

