.admin-shell header { padding:18px 24px; border:1px solid var(--line); border-radius:18px; background:var(--surface); }.admin-brand { margin-right:auto; letter-spacing:-1px; }.admin-brand span { display:block; text-align:left; letter-spacing:1.5px; text-transform:uppercase; font-size:10px; margin-top:4px; color:var(--muted); }
.admin-shell nav { padding:8px; border:1px solid var(--line); border-radius:16px; background:var(--surface); }.admin-shell nav button { display:flex; align-items:center; gap:9px; border:0; background:transparent; flex:1; justify-content:center; min-height:46px; font-size:13px; }.admin-heading { margin-top:32px; }.admin-heading h1 { margin-right:auto; font-size:30px; }
.admin-welcome { padding:30px; border-radius:20px; background:var(--control-active); color:var(--control-active-text); margin-bottom:24px; }.admin-welcome h2 { color:inherit; font-size:28px; margin:12px 0; }.admin-welcome p { font-size:10px; letter-spacing:2px; margin:0; }.admin-welcome span { font-size:14px; }
.admin-metrics article { border-radius:18px; box-shadow:0 6px 24px #35153608; }.metric-label { display:flex; align-items:center; gap:8px; font-size:12px; color:var(--muted); }.admin-metrics strong { font-variant-numeric:tabular-nums; font-size:30px; }
.admin-search { display:flex; align-items:end; justify-content:space-between; gap:16px; margin-top:28px; }.admin-search label { max-width:380px; width:100%; font-size:12px; }.admin-search > span { font-size:12px; color:var(--muted); padding-bottom:12px; }
.admin-table { border:1px solid var(--line); border-radius:16px; background:var(--surface); margin-top:16px; }.admin-table th { background:var(--control-bg); color:var(--control-text); font-size:11px; letter-spacing:.5px; padding:16px; }.admin-table td { padding:16px; line-height:1.65; }.admin-table tbody tr:hover { background:color-mix(in srgb,var(--control-active) 5%,transparent); }.admin-login { background:var(--surface); padding:32px; border:1px solid var(--line); border-radius:24px; }.admin-editor { border-radius:20px; }.admin-editor dl { display:grid; grid-template-columns:minmax(120px,1fr) 2fr; gap:8px 20px; }.admin-editor dd { overflow-wrap:anywhere; }
