.admin-title { margin-right:auto; }.admin-title h1 { font-size:clamp(28px,3vw,40px); letter-spacing:-1px; margin-bottom:8px; }.admin-title > p:last-child { font-size:14px; color:var(--muted); margin:0; }.admin-title .eyebrow { font-size:10px; margin-bottom:10px; letter-spacing:1.6px; }
.admin-shell .btn { border-radius:999px; font-size:12px; letter-spacing:.3px; min-height:42px; }.admin-notice { padding:16px 20px; border:1px solid var(--control-border); border-radius:12px; background:var(--control-bg); color:var(--control-text); }
